		/*updateMasterWmIyangWmsivdt*/
			UPDATE WMSIVDT IVDT
     			SET DELIVERY_COMPANY =  'D008'
                    , DELIVERY_NO = (SELECT MIN(MNG.COURIER_NO) FROM KEP_COURIER_MNG MNG
												WHERE MNG.BUYER = IVDT.BUYER
												AND MNG.INV_NO = IVDT.INV_NO)
					, PARCEL_ADD_DATE = SYSDATE 
					, PARCEL_ADD_USER_ID = #{USER_ID}
           WHERE INV_NO = #{INV_NO}
               AND BUYER = #{BUYER}


		/*updateHanjinWmsivdt*/
		UPDATE WMSIVDT IVDT
   		   SET DELIVERY_COMPANY = 'D011'
             , DELIVERY_NO = #{wblNo}
         WHERE BUYER = #{buyer}
           AND INV_NO = #{inv_no}
           AND DELIVERY_NO IS NULL


/*updateHanjinItemHd*/
UPDATE KEP_PARCEL_HJ 
   SET WBLNO = #{wblNo},
   	   IF_FLAG = #{flag},
       IF_DATE = SYSDATE,
       IF_MSG = #{resultMessage}
 WHERE CUSTORDNO = #{custOrdNo}
   AND IF_FLAG = 'N'


/* updateMasterWmGiReleaseTransPopHUBIVDT */
UPDATE	HUBIVDT HUB
SET		HUB.STATUS = 'R',
		HUB.SCHEDULED_DATE = #{SCHEDULED_DATE},
		HUB.HUB_IV_DATE = #{IVK_DATE},
		HUB.TOT_BOX_QTY = #{BOX_QTY},
		HUB.HUB_IV_QTY = NVL(HUB.HUB_GR_QTY, 0),
		HUB.HUB_IV_CREATE_DATE = SYSDATE,
		HUB.HUB_IV_USER_ID = #{st_user_id},
		HUB.CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
		HUB.CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'), 
		HUB.CHANGE_USER_ID = #{st_user_id}
WHERE	HUB.BUYER = #{BUYER}
AND		HUB.S_INV_NO = #{INV_NO}
AND		HUB.S_INV_SEQ = #{INV_SEQ}
AND		HUB.STATUS <> 'D'
